#ifndef  _M68K_H
#define  _M68K_H

#include "m68k_parms.H"
#include "systemc.h"
#include "ac_module.H"
#include "ac_utils.H"
#include "m68k_arch.H"
#include "m68k_isa.H"
#include "m68k_syscall.H"


class m68k: public ac_module, public m68k_arch {
private:
  typedef struct {
    uint8_t op;
    uint8_t rd;
    uint8_t zero;
    int8_t data;
  } T_Type_MoveQ;

  typedef struct {
    uint8_t op;
    uint8_t rd;
    uint8_t opmode;
    uint8_t mode;
    uint8_t reg;
  } T_Type_ALU_Reg;

  typedef struct {
    uint8_t op;
    uint8_t qdata;
    uint8_t s;
    uint8_t size;
    uint8_t mode;
    uint8_t reg;
  } T_Type_Quick;

  typedef struct {
    uint8_t op;
    uint8_t cond;
    int8_t bdisp;
  } T_Type_Branch;

  typedef struct {
    uint8_t op;
    uint8_t size;
    uint8_t dst_reg;
    uint8_t dst_mode;
    uint8_t src_mode;
    uint8_t src_reg;
  } T_Type_Move_Mem;

  typedef struct {
    uint16_t op;
  } T_Type_Halt;

  typedef struct {
    bool valid;
    void* end_rot;
    unsigned id;
    union {
      T_Type_MoveQ F_Type_MoveQ;
      T_Type_ALU_Reg F_Type_ALU_Reg;
      T_Type_Quick F_Type_Quick;
      T_Type_Branch F_Type_Branch;
      T_Type_Move_Mem F_Type_Move_Mem;
      T_Type_Halt F_Type_Halt;
    };
  } DecCacheItem ;

public:

  bool has_delayed_load;
  char* delayed_load_program;
  m68k_parms::m68k_isa ISA;
  //!Address of Interpretation Routines.
  void** IntRoutine;

  DecCacheItem* DEC_CACHE;
  DecCacheItem* instr_dec;
  bool start_up;

  //!Dispatch Method.
  inline __attribute__((always_inline)) void* dispatch();

  //!Behavior execution method.
  void behavior();

  SC_HAS_PROCESS( m68k );

  sc_event wake;

  //!Constructor.
  m68k( sc_module_name name_ ): ac_module(name_), m68k_arch(), ISA(*this) {
    SC_THREAD( behavior );
    sensitive << wake;
    has_delayed_load = false; 
    start_up=1;
    ac_id.write(globalId++);
  }

  void init_dec_cache() {
    DEC_CACHE = (DecCacheItem*) calloc(sizeof(DecCacheItem), (dec_cache_size / 2));
  }

  unsigned get_ac_pc();

  void set_ac_pc( unsigned int value );

  virtual void PrintStat();

  void init(int ac, char* av[]);

  void init();

  void set_prog_args();

  void load(char* program);

  void delayed_load(char* program);

  void stop(int status = 0);

  virtual ~m68k() {};

};
#endif  //_M68K_H

